def transform(grid):
    positions = [(r, c) for r in (1, 6, 11) for c in (1, 6)]

    def get_pattern(r, c):
        return tuple(
            tuple(grid[r + i][c + j] == 2 for j in range(4))
            for i in range(4)
        )

    patterns = [get_pattern(r, c) for r, c in positions]
    counts = [sum(sum(row) for row in p) for p in patterns]

    # The fullest tile is the one recolored 3.
    special = max(range(len(positions)), key=lambda i: counts[i])
    reference = patterns[special]

    # Consider each distinct pattern once, retaining its first occurrence.
    representatives = []
    seen = set()
    for i, pattern in enumerate(patterns):
        if i == special or pattern in seen:
            continue
        seen.add(pattern)
        distance = sum(
            reference[y][x] != pattern[y][x]
            for y in range(4) for x in range(4)
        )
        representatives.append((distance, i))

    nearest = {
        i for _, i in sorted(representatives)[:2]
    }

    out = [row[:] for row in grid]
    for i, (r, c) in enumerate(positions):
        color = 3 if i == special else (8 if i in nearest else 2)
        for y in range(4):
            for x in range(4):
                if grid[r + y][c + x] == 2:
                    out[r + y][c + x] = color
    return out
